from pathlib import Path


def replace_once(path, old, new):
    p=Path(path); text=p.read_text(encoding='utf-8')
    if old not in text:
        raise SystemExit(f'pattern not found in {path}: {old[:100]!r}')
    text=text.replace(old,new,1);p.write_text(text,encoding='utf-8')

# --- Google/Chromium drag payloads ---------------------------------------
p=Path('CanvasDropPayload.py'); text=p.read_text(encoding='utf-8')
text=text.replace("_IMAGE_EXTENSIONS = {'.png', '.jpg', '.jpeg', '.webp', '.bmp'}", "_IMAGE_EXTENSIONS = {'.png', '.jpg', '.jpeg', '.jpe', '.jfif', '.webp', '.bmp', '.gif'}")
marker="_IMG_SRC_RE = re.compile(\n    r'''(?:src|data-src|data-original)\\s*=\\s*[\"'](https?://[^\"']+)[\"']''',\n    re.IGNORECASE,\n)\n"
if marker not in text: raise SystemExit('IMG marker missing')
text=text.replace(marker, marker+"_DATA_IMAGE_RE = re.compile(\n    r'''data:image/(?:png|jpe?g|webp|gif);base64,[A-Za-z0-9+/=_-]+''',\n    re.IGNORECASE,\n)\n",1)
text=text.replace("    kind: str  # 'file' or 'url'", "    kind: str  # 'file', 'url' or bounded 'data' image URI")
needle="    # 2) Prefer explicit <img src=...> or lazy-load image attributes from HTML.\n"
insert="    # 2) Chromium/Google Images may drag an in-memory thumbnail as a data URI.\n    # Accept only common image MIME types and keep the encoded payload bounded;\n    # load_image performs the strict decoded-size validation before Pillow sees it.\n    data_candidates=[]\n    for value in items + ([raw] if raw else []):\n        for match in _DATA_IMAGE_RE.findall(unescape(str(value))):\n            candidate=str(match).strip()\n            if len(candidate) <= 28_000_000:\n                data_candidates.append(candidate)\n    if data_candidates:\n        return CanvasDropSource(data_candidates[0], 'Dropped web image', 'data')\n\n    # 3) Prefer explicit <img src=...> or lazy-load image attributes from HTML.\n"
if needle not in text: raise SystemExit('drop insertion marker missing')
text=text.replace(needle,insert,1)
text=text.replace("    # 3) Plain text/URI-list drops. Rank likely image URLs before generic URLs.", "    # 4) Plain text/URI-list drops. Rank likely image URLs before generic URLs.")
p.write_text(text,encoding='utf-8')

# --- Gartic canvas detector: rank multiple white regions + structural frame fallback ---
p=Path('GarticEngineV2.py'); text=p.read_text(encoding='utf-8')
insert_at=text.index('\ndef detect_gartic_canvas(')
helper='''\n\ndef _flood_components(mask: list[bytearray], *, min_area: int, limit: int = 48) -> list[tuple[Box, int]]:\n    """Return the largest connected mask components without assuming the largest is canvas."""\n    h=len(mask);w=len(mask[0]) if h else 0\n    visited=[bytearray(w) for _ in range(h)]\n    out=[]\n    for sy in range(h):\n        for sx in range(w):\n            if not mask[sy][sx] or visited[sy][sx]:\n                continue\n            visited[sy][sx]=1;stack=[(sx,sy)]\n            left=right=sx;top=bottom=sy;area=0\n            while stack:\n                x,y=stack.pop();area+=1\n                left=min(left,x);right=max(right,x);top=min(top,y);bottom=max(bottom,y)\n                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):\n                    if 0<=nx<w and 0<=ny<h and mask[ny][nx] and not visited[ny][nx]:\n                        visited[ny][nx]=1;stack.append((nx,ny))\n            if area>=min_area:\n                out.append(((left,top,right+1,bottom+1),area))\n    out.sort(key=lambda item:item[1],reverse=True)\n    return out[:max(1,int(limit))]\n\n\ndef _sample_white_fraction(image, box: Box, *, step: int = 6) -> float:\n    image=image.convert('RGB');l,t,r,b=box\n    hit=total=0\n    stride=max(2,int(step))\n    for y in range(max(0,t),min(image.height,b),stride):\n        for x in range(max(0,l),min(image.width,r),stride):\n            total+=1;hit+=1 if _near_white(image.getpixel((x,y))) else 0\n    return hit/max(1,total)\n'''
text=text[:insert_at]+helper+text[insert_at:]
start=text.index('def detect_gartic_canvas(')
end=text.index('\ndef choose_runtime_profile',start)
new_detect='''def detect_gartic_canvas(image, *, downsample: int = 2, min_canvas_area_ratio: float = 0.08) -> CanvasDetection:\n    """Detect Gartic's drawable canvas without assuming the largest white area wins.\n\n    Blank canvases are ranked from all sizeable near-white components. If the\n    canvas is already partly drawn, a second read-only pass looks for a large\n    non-frame component bounded by Gartic's violet frame. Aspect, frame evidence\n    and area must agree before coordinates are returned.\n    """\n    image=image.convert('RGB');w,h=image.size\n    if w<200 or h<120:\n        return CanvasDetection(False,None,0.0,0.0,0.0,0.0,'image too small')\n    step=max(1,int(downsample));sw,sh=(w+step-1)//step,(h+step-1)//step\n\n    def make_mask(predicate):\n        mask=[bytearray(sw) for _ in range(sh)]\n        for yy in range(sh):\n            y=min(h-1,yy*step)\n            for xx in range(sw):\n                x=min(w-1,xx*step)\n                if predicate(image.getpixel((x,y))):mask[yy][xx]=1\n        return mask\n\n    def full_box(small):\n        l,t,r,b=small\n        return (l*step,t*step,min(w,r*step),min(h,b*step))\n\n    candidates=[]\n    # Do not let a larger white page/panel hide a correctly-shaped canvas.\n    white_mask=make_mask(_near_white)\n    white_min=max(24,int(sw*sh*min(.035,max(.012,float(min_canvas_area_ratio)*.45))))\n    for small,area in _flood_components(white_mask,min_area=white_min):\n        candidates.append(('white',full_box(small),area))\n\n    # A drawing can fragment the white background. Gartic's violet frame usually\n    # still isolates the entire drawable surface, so rank non-frame components too.\n    structural_mask=make_mask(lambda rgb:not _purple_frame(rgb))\n    structural_min=max(36,int(sw*sh*.035))\n    for small,area in _flood_components(structural_mask,min_area=structural_min):\n        candidates.append(('frame',full_box(small),area))\n\n    best=None\n    for source,box,component_area in candidates:\n        l,t,r,b=box;bw,bh=r-l,b-t\n        if bw<max(180,int(w*.22)) or bh<max(105,int(h*.16)):\n            continue\n        aspect=bw/max(1,bh)\n        rel=abs(aspect-REFERENCE_CANVAS_ASPECT)/REFERENCE_CANVAS_ASPECT\n        aspect_score=max(0.0,1.0-rel/.22)\n        if aspect_score<=0.0:continue\n        area_ratio=(bw*bh)/max(1.0,float(w*h))\n        size_score=max(0.0,min(1.0,area_ratio/.24))\n        frame=_frame_score(image,box,pad=max(4,int(min(w,h)*.006)))\n        white=_sample_white_fraction(image,box,step=max(4,step*3))\n        cx=((l+r)*.5)/max(1,w);cy=((t+b)*.5)/max(1,h)\n        center=max(0.0,1.0-(abs(cx-.57)/.62+abs(cy-.54)/.72)*.5)\n        if source=='white':\n            confidence=.52*aspect_score+.27*white+.13*min(1.0,frame*4.0)+.05*size_score+.03*center\n            evidence_ok=white>=.48\n        else:\n            confidence=.57*aspect_score+.24*min(1.0,frame*5.0)+.11*size_score+.08*center\n            # Structural fallback is accepted only when the Gartic frame is visible.\n            evidence_ok=frame>=.018\n        confidence=max(0.0,min(1.0,confidence))\n        rank=confidence + min(.025,frame*.08)\n        if best is None or rank>best[0]:\n            best=(rank,source,box,confidence,aspect,white,frame,aspect_score,area_ratio,evidence_ok)\n\n    if best is None:\n        return CanvasDetection(False,None,0.0,0.0,0.0,0.0,'no plausible Gartic canvas region')\n    _,source,box,confidence,aspect,white,frame,aspect_score,area_ratio,evidence_ok=best\n    found=(confidence>=.68 and aspect_score>=.58 and area_ratio>=.055 and evidence_ok)\n    if found:\n        reason='gartic canvas matched' if source=='white' else 'gartic canvas matched by structural frame fallback'\n        return CanvasDetection(True,box,confidence,aspect,white,frame,reason)\n    return CanvasDetection(False,None,confidence,aspect,white,frame,'candidate needs user confirmation')\n'''
text=text[:start]+new_detect+text[end:]
p.write_text(text,encoding='utf-8')

# --- DrawBot: data URI loading, F1 Quick Start, Drop-In automatically arms Gartic canvas overlay ---
p=Path('DrawBot.py'); text=p.read_text(encoding='utf-8')
old="""    source_obj = raw_source\n    if raw_source.lower().startswith(('http://', 'https://')):\n"""
new="""    source_obj = raw_source\n    if raw_source.lower().startswith('data:image/'):\n        import base64, binascii\n        try:\n            header, encoded = raw_source.split(',', 1)\n        except ValueError as error:\n            raise ValueError('The dropped browser image data is malformed.') from error\n        if ';base64' not in header.lower():\n            raise ValueError('Only base64 browser image drops are supported.')\n        if len(encoded) > MAX_DOWNLOAD_BYTES * 2:\n            raise ValueError('The dropped browser image is too large. Choose a smaller image.')\n        try:\n            data = base64.b64decode(encoded, validate=True)\n        except (binascii.Error, ValueError) as error:\n            raise ValueError('The dropped browser image could not be decoded.') from error\n        if len(data) > MAX_DOWNLOAD_BYTES:\n            raise ValueError('The dropped browser image is larger than 20 MB. Choose a smaller image.')\n        source_obj = BytesIO(data)\n    elif raw_source.lower().startswith(('http://', 'https://')):\n"""
if old not in text:raise SystemExit('load_image marker missing')
text=text.replace(old,new,1)
old="""        try:\n            self.hotkeys.append(self.keyboard.add_hotkey('esc',self.stop.set))\n            self.hotkeys.append(self.keyboard.add_hotkey('f6',lambda:self.events.put(('toggle_pause',None))))\n        except Exception as error:\n"""
new="""        try:\n            self.hotkeys.append(self.keyboard.add_hotkey('esc',self.stop.set))\n            self.hotkeys.append(self.keyboard.add_hotkey('f6',lambda:self.events.put(('toggle_pause',None))))\n            quick=lambda:self.events.put(('quick_start',None))\n            try:\n                self.hotkeys.append(self.keyboard.add_hotkey('f1',quick,suppress=True))\n            except TypeError:\n                self.hotkeys.append(self.keyboard.add_hotkey('f1',quick))\n        except Exception as error:\n"""
if old not in text:raise SystemExit('hotkey marker missing')
text=text.replace(old,new,1)
old="""        log_event('Manual Drop-In Start armed for next image import.')\n        return True\n"""
new="""        log_event('Manual Drop-In Start armed for next image import.')\n        # Gartic users expect to drag from Google Images directly onto the game.\n        # Reuse Smart Canvas Drop automatically so the temporary OS drop target\n        # sits exactly over the detected canvas while this one-shot arm is live.\n        if self.game.get()=='Gartic Phone':\n            callback=getattr(self,'arm_smart_canvas_drop',None)\n            if callable(callback):\n                try:self.root.after(25,callback)\n                except (tk.TclError,RuntimeError,AttributeError):pass\n        return True\n"""
if old not in text:raise SystemExit('manual drop marker missing')
text=text.replace(old,new,1)
old="""    def toggle_pause(self):\n"""
new="""    def quick_start_hotkey(self):\n        \"\"\"F1 Quick Start: same setup guards as the buttons, without unsafe bypasses.\"\"\"\n        if self.activity or self.closing:return False\n        now=time.monotonic();last=float(getattr(self,'quick_start_last_monotonic',0.0) or 0.0)\n        if now-last<.70:return False\n        self.quick_start_last_monotonic=now\n        if self.game.get()=='Microsoft Paint':\n            log_event('F1 Quick Start requested for Paint; using Prepare Paint & draw flow.')\n            return DrawBotApp.start_full_drawing(self)\n        ready,message=DrawBotApp._start_guard_ready(self,require_image=True)\n        if not ready:\n            self.status.set('F1 Quick Start blocked: '+message.replace('Start locked: ','',1))\n            log_event('F1 Quick Start blocked: '+message)\n            return False\n        if not DrawBotApp._full_draw_unlocked(self):\n            if not DrawBotApp.unlock_full_drawing(self):return False\n        log_event('F1 Quick Start accepted after normal setup guards.')\n        return DrawBotApp.start_full_drawing(self)\n\n    def toggle_pause(self):\n"""
if old not in text:raise SystemExit('toggle pause marker missing')
text=text.replace(old,new,1)
old="""        elif kind=='toggle_pause':\n            self.toggle_pause()\n        elif kind=='picture_palette_complete':\n"""
new="""        elif kind=='toggle_pause':\n            self.toggle_pause()\n        elif kind=='quick_start':\n            self.quick_start_hotkey()\n        elif kind=='picture_palette_complete':\n"""
if old not in text:raise SystemExit('poll marker missing')
text=text.replace(old,new,1)
p.write_text(text,encoding='utf-8')

# UI text makes the actual drop target workflow explicit.
p=Path('StudioUI.py'); text=p.read_text(encoding='utf-8')
text=text.replace("tooltip(a.drop_in_button,'One-shot browser/game mode: after target canvas and palette are ready, the next dropped/selected/pasted image starts drawing automatically. Paint keeps the full safety chain.')",
                  "tooltip(a.drop_in_button,'One-shot browser/game mode. On Gartic Phone this also arms a temporary drop listener over the detected game canvas, so a Google/Chrome image can be released directly on Gartic and start when setup is safe. Paint keeps its normal guarded flow.')")
